'use strict';
// Source-only port tests. No node:sqlite import, DB or native process is opened.
const assert=require('node:assert/strict'), crypto=require('node:crypto');
const r=require('./metadata_reader.cjs');
const hash=x=>crypto.createHash('sha256').update(x).digest('hex');
const C={SQLITE_OK:0,SQLITE_DENY:1,SQLITE_SELECT:21,SQLITE_READ:20,SQLITE_FUNCTION:31,SQLITE_PRAGMA:19,SQLITE_INSERT:18,SQLITE_UPDATE:23,SQLITE_DELETE:9,SQLITE_ATTACH:24,SQLITE_CREATE_TABLE:2};
let cases=0;
function test(name,run){cases++;run();}
function fixture(change={}){
 const profile={schema:'ocv.retained-clone-metadata-profile.v1',sourceSha:'a'.repeat(40),indexDigest:'sha256:'+'1'.repeat(64),platformDigest:'sha256:'+'2'.repeat(64),configDigest:'sha256:'+'3'.repeat(64),grantSha256:'b'.repeat(64),dataset:{testDiskId:'1',filesystemUuid:'synthetic-fixture',sourceSnapshotId:'2'},rows:[],admission:{ownerSessionId:'c'.repeat(32),vmId:'3',bootId:'00000000-0000-0000-0000-000000000001',sourceOwnerProofSha256:'d'.repeat(64),readOnlyMountsVerified:true,noWritersVerified:true,exactDatasetVerified:true,controllerHardQuerySeconds:60,controllerWholeActionSeconds:120,noRetry:true,established:true}};
 const files=new Map(),fds=new Map();let fd=10,opened=0,closed=0,dbs=0,statements=0,stmtClosed=0;
 const st=(dir,ino)=>({dev:1n,ino:BigInt(ino),size:dir?4096n:4096n,uid:dir?0n:1000n,gid:dir?0n:1000n,nlink:1n,mode:BigInt(dir?0o40755:0o100600),mtimeNs:1n,ctimeNs:1n,isFile:()=>!dir,isDirectory:()=>dir,isSymbolicLink:()=>false});
 files.set('/metadata',st(true,1));
 for(let n=0;n<11;n++){
  const agent=n===0?null:'synthetic-'+String(n).padStart(2,'0'),relative=n===0?'state/openclaw.sqlite':'agents/'+agent+'/agent/openclaw-agent.sqlite';
  const name='/metadata/db-'+String(n).padStart(2,'0');const main=st(false,100+n);files.set(name,st(true,10+n));files.set(name+'/main.sqlite',main);
  profile.rows.push({ordinal:n,relativePath:relative,pathSha256:hash(relative),role:n===0?'global':'agent',agentId:agent,files:{main:Object.fromEntries(['dev','ino','size','uid','gid','nlink','mode','mtimeNs','ctimeNs'].map(k=>[k,String(main[k])])),wal:{state:'absent',identity:null},shm:{state:'absent',identity:null},journal:{state:'absent',identity:null}}});
 }
 const fs={constants:{O_RDONLY:0,O_NOFOLLOW:1,O_NONBLOCK:2},lstatSync(name){if(change.stat)return change.stat(name,files);if(!files.has(name))throw {code:'ENOENT',message:'sensitive path'};return files.get(name);},realpathSync:x=>x,openSync(name,flags){assert.equal(flags,3);opened++;fds.set(++fd,files.get(name));return fd;},fstatSync:fd=>change.fdDrift?{...fds.get(fd),ino:99999n}:fds.get(fd),closeSync(fd){closed++;if(change.fdClose)throw {code:'EIO'};fds.delete(fd);},readFileSync(name){assert.equal(name,'/proc/self/mountinfo');let x=profile.rows.map((row,n)=>(n+10)+' 1 1:1 / /metadata/db-'+String(n).padStart(2,'0')+'/main.sqlite '+(change.rw?'rw':'ro')+' - ext4 /dev/synthetic ro').join('\n');if(change.extraMount)x+='\n99 1 1:1 / /metadata/unapproved ro - ext4 /dev/synthetic ro';return x;}};
 class Database{
  constructor(name,options){dbs++;assert.deepEqual(options,{readOnly:true,allowExtension:false,enableForeignKeyConstraints:false,enableDoubleQuotedStringLiterals:false,timeout:0,defensive:true,limits:{length:262144,sqlLength:4096,attach:0}});this.n=Number(name.match(/db-([0-9]+)/)[1]);if(change.openError)throw {errcode:14,message:'credential private'};}
  setAuthorizer(fn){this.auth=fn;}
  enableLoadExtension(value){assert.equal(value,false);}
  exec(sql){assert.ok(sql===r.SQL.only||sql===r.SQL.trusted);assert.equal(this.auth(C.SQLITE_PRAGMA,sql===r.SQL.only?'query_only':'trusted_schema',sql===r.SQL.only?'ON':'OFF',null,null),C.SQLITE_OK);}
  prepare(sql){const key=Object.keys(r.SQL).find(k=>r.SQL[k]===sql);assert.ok(key);statements++;assert.equal(this.auth(C.SQLITE_SELECT,null,null,null,null),C.SQLITE_OK);const row=profile.rows[this.n];let values;
   switch(key){case'onlyRead':values=[{query_only:1}];break;case'trustedRead':values=[{trusted_schema:0}];break;case'version':values=[{version:'3.50.4'}];break;case'uv':values=[{user_version:this.n===0?20:25}];break;case'catalog':values=[{type:'table'}];break;case'tables':values=(this.n===0?['schema_meta','agent_databases','agent_deletion_journal','migration_sources']:['schema_meta']).map(name=>({schema:'main',name,type:'table',strict:1}));break;case'schema':values=[{role:row.role,schema_version:this.n===0?20:25,agent_id:row.agentId,app_version:'2026.10.5'}];break;case'registry':values=profile.rows.slice(1).map(row=>({agent_id:row.agentId,path:row.relativePath,schema_version:25}));break;case'deletion':values=[];break;case'held':values=[];break;default:throw Error('unselected SQL');}
   if(change.queryError&&key===change.queryError)throw {errcode:23,message:'private SQL',sql:'sensitive'};
   if(change.rows)values=change.rows(key,values,this.n);
   return {iterate(){return values.values();},close(){stmtClosed++;if(change.stmtClose&&key==='catalog')throw {errcode:5,message:'private close'};}};
  }
  close(){if(change.afterClose)change.afterClose(files,this.n);if(change.dbClose)throw {errcode:5,message:'sensitive close'};}
 }
 const io={fs,DatabaseSync:Database,constants:C,nodeVersion:'24.22.1',uid:1000,gid:1000,now:()=>change.expired?60000:0};
 return {profile,io,files,counts:()=>({opened,closed,dbs,statements,stmtClosed})};
}
test('source-only full11DB metadata/registry/hygiene lifecycle',()=>{const x=fixture(),v=r.collect(x.profile,x.io);assert.equal(v.status,'METADATA_CONSISTENT');assert.equal(v.rows.length,11);assert.equal(v.integrityFreshnessMigrationProductionEstablished,false);assert.deepEqual(x.counts(),{opened:11,closed:11,dbs:11,statements:80,stmtClosed:80});assert.ok(!JSON.stringify(v).includes('synthetic-'));});
test('private draft/unknownfreshness refuses before anyDBopen',()=>{for(const field of ['established','noWritersVerified','readOnlyMountsVerified','exactDatasetVerified']){const x=fixture();x.profile.admission[field]=null;assert.throws(()=>r.collect(x.profile,x.io));assert.equal(x.counts().dbs,0);}});
test('unknown/partial sidecar states refused before open',()=>{for(const kind of ['unknown','partial','journal']){const x=fixture();const f=x.profile.rows[0].files;if(kind==='unknown')f.wal.state=null;if(kind==='partial'){f.wal={state:'present',identity:f.main};}if(kind==='journal')f.journal={state:'present',identity:f.main};assert.throws(()=>r.collect(x.profile,x.io));assert.equal(x.counts().dbs,0);}});
test('fixed authorizer denies applicationdata/write/attach/function/trigger routes',()=>{const a=r.authorizer(C,true),agent=r.authorizer(C,false);assert.equal(a(C.SQLITE_READ,'schema_meta','role','main',null),0);for(const args of [[C.SQLITE_INSERT,'schema_meta',null,'main',null],[C.SQLITE_UPDATE,'schema_meta','role','main',null],[C.SQLITE_ATTACH,null,null,null,null],[C.SQLITE_READ,'sessions','body','main',null],[C.SQLITE_READ,'schema_meta','role','temp',null],[C.SQLITE_READ,'schema_meta','role','main','view'],[C.SQLITE_FUNCTION,null,'load_extension',null,null],[C.SQLITE_PRAGMA,'writable_schema','ON',null,null],[C.SQLITE_PRAGMA,'query_only','OFF',null,null],[C.SQLITE_PRAGMA,'trusted_schema','ON',null,null]])assert.equal(a(...args),1);assert.equal(agent(C.SQLITE_READ,'agent_databases','path','main',null),1);});
test('read-only mounts and namedidentity failures stopbeforeDBopen',()=>{for(const mode of ['rw','extraMount','symlink','owner']){const x=fixture({[mode]:true});if(mode==='symlink')x.files.get('/metadata/db-00/main.sqlite').isSymbolicLink=()=>true;if(mode==='owner')x.files.get('/metadata/db-00/main.sqlite').uid=0n;const v=r.collect(x.profile,x.io);assert.equal(v.status,'INCOMPLETE');assert.equal(x.counts().dbs,0);}});
test('metadata views/virtualtables refused without rowqueries',()=>{for(const type of ['view','virtual']){const x=fixture({rows:(k,v)=>k==='tables'?v.map(t=>({...t,type})):v}),v=r.collect(x.profile,x.io);assert.equal(v.failure.code,127);assert.equal(v.failure.stage,5);}});
test('schema20/25/app/owner mismatches refused without rawvalueoutput',()=>{for(const bad of [{schema_version:24},{app_version:'private-credential'},{agent_id:'private-credential'},{role:'other'}]){const x=fixture({rows:(k,v)=>k==='schema'?v.map(row=>({...row,...bad})):v}),v=r.collect(x.profile,x.io);assert.equal(v.failure.code,129);assert.equal(v.failure.stage,6);assert.ok(!JSON.stringify(v).includes('private-credential'));}});
test('registry foreign/duplicate/missing scoped agents refused',()=>{for(const kind of ['foreign','duplicate','missing']){const x=fixture({rows:(k,v)=>k==='registry'?(kind==='foreign'?[{agent_id:'unapproved',path:'/private',schema_version:25}]:kind==='duplicate'?[v[0],v[0]]:v.slice(1)):v}),v=r.collect(x.profile,x.io);assert.equal(v.failure.code,130);assert.equal(v.failure.stage,7);}});
test('deletion and heldmetadata never silentlypass',()=>{for(const kind of ['pending','retained','held','malformed']){const x=fixture({rows:(k,v)=>k==='deletion'&&['pending','retained'].includes(kind)?[{cleanup_completed:kind==='pending'?0:1,delete_files:kind==='retained'?0:1}]:k==='held'&&['held','malformed'].includes(kind)?[{report:kind==='held'?JSON.stringify({held:[{path:'/private-credential'}]}):'private-credential'}]:v}),v=r.collect(x.profile,x.io);assert.equal(v.status,'INCOMPLETE');assert.equal(v.failure.stage,8);assert.ok(!JSON.stringify(v).includes('private-credential'));}});
test('catalogoverflow bounded/refused and statementclosed',()=>{const x=fixture({rows:(k,v)=>k==='catalog'?Array.from({length:513},()=>({type:'table'})):v}),v=r.collect(x.profile,x.io);assert.equal(v.failure.code,121);assert.equal(v.failure.stage,5);assert.equal(x.counts().statements,x.counts().stmtClosed);assert.equal(x.counts().opened,x.counts().closed);});
test('late fileidentity drift and cleanupfailures stayINCOMPLETE',()=>{let once=false;const x=fixture({afterClose:(files)=>{if(!once){once=true;files.get('/metadata/db-00/main.sqlite').mtimeNs=2n;}}}),v=r.collect(x.profile,x.io);assert.equal(v.failure.code,111);assert.equal(v.failure.stage,9);for(const change of [{dbClose:true},{fdClose:true},{queryError:'schema',dbClose:true}]){const y=fixture(change),z=r.collect(y.profile,y.io);assert.equal(z.status,'INCOMPLETE');assert.ok(Object.hasOwn(z,'cleanupFailureCode'));if(change.queryError)assert.equal(z.failure.stage,6);}});
test('numericSQLite failures retained with no retry or rawerror',()=>{for(const change of [{openError:true},{queryError:'schema'}]){const x=fixture(change),v=r.collect(x.profile,x.io);assert.equal(v.status,'INCOMPLETE');assert.equal(x.counts().dbs,1);assert.ok([14,23].includes(v.failure.code));assert.ok(!JSON.stringify(v).includes('credential')&&!JSON.stringify(v).includes('sensitive'));}});
test('openeddescriptor isowned beforefstat identityrefusal',()=>{const x=fixture({fdDrift:true}),v=r.collect(x.profile,x.io);assert.equal(v.failure.code,110);assert.equal(x.counts().opened,1);assert.equal(x.counts().closed,1);assert.equal(x.counts().dbs,0);});
test('statementclosefailure preserves originaloverflow diagnostic',()=>{const x=fixture({stmtClose:true,rows:(k,v)=>k==='catalog'?Array.from({length:513},()=>({type:'table'})):v}),v=r.collect(x.profile,x.io);assert.equal(v.failure.code,121);assert.equal(v.cleanupFailureCode,5);assert.equal(v.failure.stage,5);assert.equal(x.counts().opened,x.counts().closed);});
test('profiledescriptor exactreadonlymode/source/endidentity guards',()=>{const raw=Buffer.from('{}'),p={dev:1n,ino:2n,size:2n,uid:0n,gid:0n,nlink:1n,mode:0o100444n,mtimeNs:1n,ctimeNs:1n,isFile:()=>true,isSymbolicLink:()=>false};for(const kind of ['good','mode','symlink','drift','grow','sha']){let closed=0;const port={constants:{O_RDONLY:0,O_NOFOLLOW:1,O_NONBLOCK:2},lstatSync:()=>({...p,mode:kind==='mode'?0o100644n:p.mode,isSymbolicLink:()=>kind==='symlink'}),openSync:(name,flags)=>{assert.equal(name,'/run/metadata-profile.json');assert.equal(flags,3);return 1;},fstatSync:()=>({...p,ino:kind==='drift'?3n:2n}),readSync:(_fd,b,offset,length)=>{const data=kind==='grow'?Buffer.from('{}x'):raw;if(offset>=data.length)return 0;return data.copy(b,offset,offset,offset+length);},closeSync:()=>closed++};if(kind==='good')assert.deepEqual(r.readProfile(port,hash(raw)),raw);else assert.throws(()=>r.readProfile(port,kind==='sha'?'0'.repeat(64):hash(raw)));assert.equal(closed,['mode','symlink'].includes(kind)?0:1);}});
test('completed deletion canonicalidentity/locator/JSON remainsclosed',()=>{const good={agent_id:'deleted-synthetic',agent_dir:'agents/deleted-synthetic/agent',paths:'["agents/deleted-synthetic/agent/openclaw-agent.sqlite"]',cleanup_completed:1,delete_files:1};for(const change of [{},{agent_id:'../not-canonical'},{agent_dir:'/outside'},{paths:'not-json'},{paths:'["/outside"]'}]){const x=fixture({rows:(k,v)=>k==='deletion'?[{...good,...change}]:v}),v=r.collect(x.profile,x.io);assert.equal(v.status,Object.keys(change).length?'INCOMPLETE':'METADATA_CONSISTENT');if(Object.keys(change).length)assert.equal(v.failure.stage,8);assert.ok(!JSON.stringify(v).includes('outside'));}});
